Object.assign((resources as any).en.translation, enPageExtensions);

for (const lang of Object.keys(resources)) {
  if (lang === "en") continue;
  const tr = (resources as any)[lang]?.translation;
  if (!tr) continue;
  for (const [key, value] of Object.entries((resources as any).en.translation)) {
    if (!key.startsWith("jobs.")) continue;
    if (!(key in tr)) tr[key] = value;
  }
}

const resourcesBeforeOverrides = JSON.parse(JSON.stringify(resources)) as any;

