const CP1252_REVERSE: Record<string, number> = {
  "€": 0x80,
  "‚": 0x82,
  "ƒ": 0x83,
  "„": 0x84,
  "…": 0x85,
  "†": 0x86,
  "‡": 0x87,
  "ˆ": 0x88,
  "‰": 0x89,
  "Š": 0x8a,
  "‹": 0x8b,
  "Œ": 0x8c,
  "Ž": 0x8e,
  "‘": 0x91,
  "’": 0x92,
  "“": 0x93,
  "”": 0x94,
  "•": 0x95,
  "–": 0x96,
  "—": 0x97,
  "˜": 0x98,
  "™": 0x99,
  "š": 0x9a,
  "›": 0x9b,
  "œ": 0x9c,
  "ž": 0x9e,
  "Ÿ": 0x9f,
};

const MOJIBAKE_HINT_CHARS = "ÃÂâÐØÙæå";
const utf8Decoder = new TextDecoder("utf-8", { fatal: false });
const EXTRA_MOJIBAKE_HINT_CHARS = "\u00C3\u00C2\u00E2\u00D0\u00D8\u00D9\u00E6\u00E5\u00E7\u00E8\u00E9\u00EF\u00E4\u00F6\u00FC\u00F1\u00F8";
const hasMojibakeHint = (value: string): boolean =>
  [...value].some((ch) => MOJIBAKE_HINT_CHARS.includes(ch) || EXTRA_MOJIBAKE_HINT_CHARS.includes(ch));

const toCp1252Bytes = (value: string): Uint8Array => {
  const bytes: number[] = [];
  for (const ch of value) {
    const code = ch.charCodeAt(0);
    if (code <= 0xff) {
      bytes.push(code);
    } else if (Object.prototype.hasOwnProperty.call(CP1252_REVERSE, ch)) {
      bytes.push(CP1252_REVERSE[ch]);
    } else {
      bytes.push(0x3f);
    }
  }
  return new Uint8Array(bytes);
};

const mojibakeScore = (value: string): number => {
  let score = 0;
  for (const ch of value) {
    if (ch === "\uFFFD") score += 3;
    if (MOJIBAKE_HINT_CHARS.includes(ch) || EXTRA_MOJIBAKE_HINT_CHARS.includes(ch)) score += 1;
  }
  return score;
};

const maybeDecodeMojibake = (value: string): string => {
  if (!value || !hasMojibakeHint(value)) {
    return value;
  }

  let current = value;
  for (let i = 0; i < 3; i += 1) {
    const decoded = utf8Decoder.decode(toCp1252Bytes(current));
    if (!decoded || decoded === current) break;
    if (mojibakeScore(decoded) > mojibakeScore(current)) break;
    current = decoded;
    if (!hasMojibakeHint(current)) break;
  }
  return current;
};

const isMostlyQuestionMarks = (value: string): boolean => {
  const cleaned = value.replace(/[\s()[\]{}:;,.!'"`|\\/_-]/g, "");
  if (!cleaned) return false;
  const questionCount = [...cleaned].filter((ch) => ch === "?").length;
  return questionCount > 0 && questionCount / cleaned.length >= 0.6;
};

const normalizeTranslationMap = (map: Record<string, unknown>): void => {
  for (const [key, raw] of Object.entries(map)) {
    if (typeof raw !== "string") continue;
    map[key] = maybeDecodeMojibake(raw);
  }
};

for (const lang of Object.keys(resources)) {
  const tr = (resources as any)[lang]?.translation;
  if (!tr) continue;
  normalizeTranslationMap(tr);
}

for (const lang of Object.keys(resources)) {
  const tr = (resources as any)[lang]?.translation;
  if (!tr) continue;
  const base = resourcesBeforeOverrides?.[lang]?.translation || {};
  for (const [key, currentValue] of Object.entries(tr)) {
    if (typeof currentValue !== "string") continue;
    if (!isMostlyQuestionMarks(currentValue)) continue;

    const baseValue = base[key];
    const enValue = (resources as any).en?.translation?.[key];
    const fallback =
      typeof baseValue === "string" && baseValue.trim().length > 0
        ? baseValue
        : typeof enValue === "string"
        ? enValue
        : currentValue;
    tr[key] = maybeDecodeMojibake(fallback);
  }
}

